    streets,
    ramps,
    getNight: () => isNight,
    getWeather: () => wx,
    followShadows,
    followMirror,
    setPlanar(on: boolean) {
      planarOk = !!on;
      if (mirror) mirror.visible = planarOk;
    },
    sunDir: lightAim,
    tick,
    setTime,
    setClock,
    getClock: () => clock,
    setWeather,
    setLod,
    // RSH-019-OVERLAY-BEGIN:world-dispose
    dispose() {
      if (disposed) return;
      disposed = true;
      const tracker = createObject3DDisposalTracker();
      disposeObject3D(group, tracker);
      const disposedSceneResources = new Set<Disposable>([
        ...tracker.geometries,
        ...tracker.materials,
      ]);
      for (let index = bag.length - 1; index >= 0; index -= 1) {
        const resource = bag[index];
        if (disposedSceneResources.has(resource)) continue;
        try {
          resource.dispose();
        } catch {
          /* continue releasing the remaining owned resources */
        }
      }
      bag.length = 0;
      dir.shadow.map?.dispose();
      dir.shadow.mapPass?.dispose();
      dirNear.shadow.map?.dispose();
      dirNear.shadow.mapPass?.dispose();
    },
    // RSH-019-OVERLAY-END:world-dispose
  });
}

/** A material owns its daytime colour; procedural water has no catalogue-body index. */
export type WaterClockMaterial = {
  color: { setHex(value: number): unknown; multiplyScalar(value: number): unknown };
  envMapIntensity: number;
  roughness: number;
  opacity: number;
};
export type WaterClockEntry = {
  readonly material: WaterClockMaterial;
  readonly baseColor: number;
};

/** Reapply the existing water clock recipe from the base colour on every update. */
export function applyWaterClock(entries: readonly WaterClockEntry[], nightAmount: number): void {
  if (!Number.isFinite(nightAmount)) throw new RangeError('Water night amount must be finite');
  const n = Math.max(0, Math.min(1, nightAmount));
  for (const { material, baseColor } of entries) {
    material.color.setHex(baseColor);
    if (n > 0.35) material.color.multiplyScalar(1 + (0.5 - 1) * n);
    material.envMapIntensity = 1.7 + (2.6 - 1.7) * n;
    material.roughness = 0.08 + (0.03 - 0.08) * n;
    material.opacity = 0.82 + (0.9 - 0.82) * n;
  }
}

